on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  paldean_wonders_cards integer;
  paldean_wonders_packs integer;
  paldean_wonders_odds integer;
begin
  select count(*)
  into paldean_wonders_cards
  from public.cards
  where set_id = 'B2a';

  select count(*)
  into paldean_wonders_packs
  from public.packs
  where set_id = 'B2a';

  select count(*)
  into paldean_wonders_odds
  from public.card_pack_odds
  where pack_id = 'b2a-paldean-wonders';

  if paldean_wonders_cards <> 131 then
    raise exception
      'Expected 131 Paldean Wonders cards, found %',
      paldean_wonders_cards;
  end if;

  if paldean_wonders_packs <> 1 then
    raise exception
      'Expected 1 Paldean Wonders pack, found %',
      paldean_wonders_packs;
  end if;

  if paldean_wonders_odds <> 131 then
    raise exception
      'Expected 131 Paldean Wonders odds rows, found %',
      paldean_wonders_odds;
  end if;
end
$$;

commit;

-- Expected: 131 total records for the Paldean Wonders pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b2a-paldean-wonders'
group by cards.rarity
order by min(cards.collector_number);
